WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_sl_essay_opening'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '凤头起笔', 'kp-sl-essay-opening', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "大作文：凤头起笔"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "开门见山，绝不啰嗦。150字内必须让阅卷老师看到你的总论点。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、万能开头模板（背景+问题+论点）"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“随着（时代大背景，如：经济的快速发展/城市化进程的推进），（核心主题）取得了显著成就。然而，我们也应清醒地看到，当前在（某个领域）仍存在（材料中提炼的问题）等乱象。这不仅影响了...，更制约了...。因此，我们必须（亮出总论点对策），方能破解困局，实现（好的愿景）。”"}]}]}$$ AS jsonb), NULL, '凤头起笔的核心考点与高分作答技巧。', category_node.id, CAST('["申论", "大作文", "凤头开头"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_sl_essay_opening", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
